sql_query:
SELECT "Control arm"
FROM clinical_trials
WHERE "Included in MA" = 'Yes' AND "Name of ICI" = 'Ipilimumab' AND "Trial phase" = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control arm" AS source_value FROM clinical_trials WHERE "Included in MA" = 'Yes' AND "Name of ICI" = 'Ipilimumab' AND "Trial phase" = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_control_category(source_value) AS "control_category"
FROM base;
